public class BeanDeserializerBase_deserializeFromDouble_TriageGen0Test {

    private BeanDeserializerBase beanDeserializerBase;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private ValueInstantiator mockInstantiator;
    private JsonDeserializer mockDelegate;

    // Subclass to make the protected class testable
    private static class TestBeanDeserializer extends BeanDeserializerBase {
        protected TestBeanDeserializer(BeanDeserializerBase src) {
            super(src);
        }

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(com.fasterxml.jackson.databind.NameTransformer unwrapper) { return null; }
        @Override
        public BeanDeserializerBase withObjectIdReader(com.fasterxml.jackson.databind.ObjectIdReader oir) { return this; }
        @Override
        public BeanDeserializerBase withIgnorableProperties(java.util.Set<String> ignorableProps) { return this; }
        @Override
        public BeanDeserializerBase withBeanProperties(BeanPropertyMap props) { return this; }
        @Override
        protected BeanDeserializerBase asArrayDeserializer() { return this; }
        @Override
        public void resolve(DeserializationContext ctxt) throws JsonMappingException {}
        @Override
        public JsonDeserializer<?> createContextual(DeserializationContext ctxt, com.fasterxml.jackson.databind.JsonDeserializer.Context context) { return null; }
        @Override
        public Object deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
        @Override
        public Object deserializeWithType(JsonParser p, DeserializationContext ctxt, com.fasterxml.jackson.databind.deser.std.TypeDeserializer typeDeserializer) throws IOException { return null; }
        @Override
        protected Object _deserializeUsingPropertyBased(JsonParser p, DeserializationContext ctxt) throws IOException, com.fasterxml.jackson.core.JsonProcessingException { return null; }
    }

    @Before
    public void setUp() throws Exception {
        // Create a base instance via the protected constructor
        // Since we can't easily mock the complex builder/description, we use a dummy base
        BeanDeserializerBase base = mock(BeanDeserializerBase.class);
        beanDeserializerBase = spy(new TestBeanDeserializer(base));

        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockInstantiator = mock(ValueInstantiator.class);
        mockDelegate = mock(JsonDeserializer.class);

        // Inject private fields using reflection
        setField(beanDeserializerBase, "_valueInstantiator", mockInstantiator);
        setField(beanDeserializerBase, "_delegateDeserializer", mockDelegate);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = BeanDeserializerBase.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testDeserializeFromDouble_DirectInstantiation() throws IOException {
        when(mockParser.getNumberType()).thenReturn(NumberType.DOUBLE);
        when(mockParser.getDoubleValue()).thenReturn(123.45);
        when(mockInstantiator.canCreateFromDouble()).thenReturn(true);
        when(mockInstantiator.createFromDouble(any(), eq(123.45))).thenReturn("Result");

        Object result = beanDeserializerBase.deserializeFromDouble(mockParser, mockContext);

        assertEquals("Result", result);
        verify(mockInstantiator).createFromDouble(mockContext, 123.45);
    }

    @Test
    public void testDeserializeFromFloat_DirectInstantiation() throws IOException {
        when(mockParser.getNumberType()).thenReturn(NumberType.FLOAT);
        when(mockParser.getDoubleValue()).thenReturn(1.2f);
        when(mockInstantiator.canCreateFromDouble()).thenReturn(true);
        when(mockInstantiator.createFromDouble(any(), eq(1.2f))).thenReturn("FloatResult");

        Object result = beanDeserializerBase.deserializeFromDouble(mockParser, mockContext);

        assertEquals("FloatResult", result);
    }

    @Test
    public void testDeserializeFromDouble_ViaDelegate() throws IOException {
        when(mockParser.getNumberType()).thenReturn(NumberType.DOUBLE);
        when(mockInstantiator.canCreateFromDouble()).thenReturn(false);
        when(mockDelegate.deserialize(mockParser, mockContext)).thenReturn("DelegatedObject");
        when(mockInstantiator.createUsingDelegate(eq(mockContext), eq("DelegatedObject"))).thenReturn("FinalObject");

        Object result = beanDeserializerBase.deserializeFromDouble(mockParser, mockContext);

        assertEquals("FinalObject", result);
    }

    @Test
    public void testDeserializeFromDouble_ViaDelegateWithInjection() throws IOException {
        when(mockParser.getNumberType()).thenReturn(NumberType.DOUBLE);
        when(mockInstantiator.canCreateFromDouble()).thenReturn(false);
        when(mockDelegate.deserialize(mockParser, mockContext)).thenReturn("DelegatedObject");
        when(mockInstantiator.createUsingDelegate(any(), any())).thenReturn("InjectedObject");

        // Mock injectables
        setField(beanDeserializerBase, "_injectables", new java.util.HashSet<>());

        Object result = beanDeserializerBase.deserializeFromDouble(mockParser, mockContext);

        assertEquals("InjectedObject", result);
        verify(beanDeserializerBase).injectValues(eq(mockContext), eq("InjectedObject"));
    }

    @Test
    public void testDeserializeFromNonNumberType_ViaDelegate() throws IOException {
        // If type is not DOUBLE/FLOAT, it checks for delegate
        when(mockParser.getNumberType()).thenReturn(NumberType.INT);
        when(mockDelegate.deserialize(mockParser, mockContext)).thenReturn("DelegatedInt");
        when(mockInstantiator.createUsingDelegate(eq(mockContext), eq("DelegatedInt"))).thenReturn("FinalInt");

        Object result = beanDeserializerBase.deserializeFromDouble(mockParser, mockContext);

        assertEquals("FinalInt", result);
    }

    @Test
    public void testDeserializeFromNonNumberType_NoDelegate_HandleMissing() throws IOException {
        when(mockParser.getNumberType()).thenReturn(NumberType.INT);
        when(mockParser.getNumberValue()).thenReturn(42);
        when(mockInstantiator.canCreateFromDouble()).thenReturn(true); // irrelevant here

        // Ensure delegate is null
        setField(beanDeserializerBase, "_delegateDeserializer", null);

        when(mockContext.handleMissingInstantiator(any(), eq(mockParser), anyString(), eq(42L)))
                .thenReturn("MissingError");

        Object result = beanDeserializerBase.deserializeFromDouble(mockParser, mockContext);

        assertEquals("MissingError", result);
    }
}
